#!/usr/bin/env python3
# Task-scoped helper: append exactly one final slide containing exactly
# "Thank you for your attention" to Q4_financial_report.pptx.
# Pure standard-library OOXML edit; no third-party dependencies.
import os
import posixpath
import re
import sys
import zipfile
from html import escape
from xml.etree import ElementTree as ET

DEFAULT_SRC = "Q4_financial_report.pptx"
PHRASE = "Thank you for your attention"

P_NS = "http://schemas.openxmlformats.org/presentationml/2006/main"
A_NS = "http://schemas.openxmlformats.org/drawingml/2006/main"
R_NS = "http://schemas.openxmlformats.org/officeDocument/2006/relationships"
REL_NS = "http://schemas.openxmlformats.org/package/2006/relationships"
SLIDE_REL_TYPE = "http://schemas.openxmlformats.org/officeDocument/2006/relationships/slide"
LAYOUT_REL_TYPE = "http://schemas.openxmlformats.org/officeDocument/2006/relationships/slideLayout"
MASTER_REL_TYPE = "http://schemas.openxmlformats.org/officeDocument/2006/relationships/slideMaster"
SLIDE_CONTENT_TYPE = "application/vnd.openxmlformats-officedocument.presentationml.slide+xml"


def q(ns, tag):
    return "{%s}%s" % (ns, tag)


def rel_map(data, rels_part):
    out = {}
    try:
        root = ET.fromstring(data[rels_part])
    except Exception:
        return out
    for el in root.findall(q(REL_NS, "Relationship")):
        out[el.get("Id")] = (el.get("Type"), el.get("Target"))
    return out


def part_from_rel(base_dir, target):
    if not target:
        return None
    if target.startswith("/"):
        return target.lstrip("/")
    return posixpath.normpath(posixpath.join(base_dir, target))


def srgb_color(el):
    if el is None:
        return None
    node = el.find(".//" + q(A_NS, "srgbClr"))
    if node is not None and node.get("val"):
        return node.get("val").upper()
    node = el.find(".//" + q(A_NS, "sysClr"))
    if node is not None and node.get("lastClr"):
        return node.get("lastClr").upper()
    return None


def part_bg(data, part):
    if not part or part not in data:
        return None
    try:
        root = ET.fromstring(data[part])
    except Exception:
        return None
    return srgb_color(root.find(".//" + q(P_NS, "bg")))


def theme_info(data):
    info = {"dk1": None, "lt1": None, "major": None}
    theme_part = next((p for p in data if re.fullmatch(r"ppt/theme/theme\d+\.xml", p)), None)
    if not theme_part:
        return info
    try:
        root = ET.fromstring(data[theme_part])
    except Exception:
        return info
    cs = root.find(".//" + q(A_NS, "clrScheme"))
    if cs is not None:
        info["dk1"] = srgb_color(cs.find(q(A_NS, "dk1")))
        info["lt1"] = srgb_color(cs.find(q(A_NS, "lt1")))
    fs = root.find(".//" + q(A_NS, "fontScheme"))
    if fs is not None:
        maj = fs.find(q(A_NS, "majorFont"))
        if maj is not None:
            lat = maj.find(q(A_NS, "latin"))
            if lat is not None and lat.get("typeface"):
                info["major"] = lat.get("typeface")
    return info


def build_slide_xml(cx, cy, phrase, color, font):
    x = int(cx * 0.08)
    w = cx - 2 * x
    h = int(cy * 0.24)
    y = (cy - h) // 2
    off = '<a:off x="%d" y="%d"/>' % (x, y)
    ext = '<a:ext cx="%d" cy="%d"/>' % (w, h)
    xml = (
        '<?xml version="1.0" encoding="UTF-8" standalone="yes"?>\n'
        '<p:sld xmlns:a="%s" xmlns:r="%s" xmlns:p="%s">'
        "<p:cSld><p:spTree>"
        '<p:nvGrpSpPr><p:cNvPr id="1" name=""/><p:cNvGrpSpPr/><p:nvPr/></p:nvGrpSpPr>'
        '<p:grpSpPr><a:xfrm><a:off x="0" y="0"/><a:ext cx="0" cy="0"/>'
        '<a:chOff x="0" y="0"/><a:chExt cx="0" cy="0"/></a:xfrm></p:grpSpPr>'
        '<p:sp><p:nvSpPr><p:cNvPr id="2" name="Thank You"/>'
        '<p:cNvSpPr txBox="1"/><p:nvPr/></p:nvSpPr>'
        "<p:spPr><a:xfrm>%s%s</a:xfrm>"
        '<a:prstGeom prst="rect"><a:avLst/></a:prstGeom>'
        "<a:noFill/><a:ln><a:noFill/></a:ln></p:spPr>"
        '<p:txBody><a:bodyPr rtlCol="0" anchor="ctr"/><a:lstStyle/>'
        '<a:p><a:pPr algn="ctr"/>'
        '<a:r><a:rPr lang="en-US" sz="4000" dirty="0" typeface="%s">'
        '<a:solidFill><a:srgbClr val="%s"/></a:solidFill></a:rPr>'
        "<a:t>%s</a:t></a:r>"
        '<a:endParaRPr lang="en-US" dirty="0"/></a:p></p:txBody>'
        "</p:sp></p:spTree></p:cSld></p:sld>"
    ) % (A_NS, R_NS, P_NS, off, ext, escape(font, quote=True), color, escape(phrase, quote=False))
    return xml


def build_rels_xml(layout_target):
    return (
        '<?xml version="1.0" encoding="UTF-8" standalone="yes"?>\n'
        '<Relationships xmlns="%s">'
        '<Relationship Id="rId1" Type="%s" Target="%s"/>'
        "</Relationships>" % (REL_NS, LAYOUT_REL_TYPE, layout_target)
    )


def main():
    args = [a for a in sys.argv[1:] if a.lower().endswith(".pptx")]
    src = args[0] if args else DEFAULT_SRC
    if not os.path.exists(src):
        print("ERROR: %s not found under %s" % (src, os.getcwd()))
        return 2

    with zipfile.ZipFile(src) as z:
        names = z.namelist()
        data = {n: z.read(n) for n in names}

    for req in ("ppt/presentation.xml", "ppt/_rels/presentation.xml.rels", "[Content_Types].xml"):
        if req not in data:
            print("ERROR: missing part %s in %s" % (req, src))
            return 2

    pres = ET.fromstring(data["ppt/presentation.xml"])
    sld_id_lst = pres.find(".//" + q(P_NS, "sldIdLst"))
    if sld_id_lst is None:
        print("ERROR: no sldIdLst found in presentation")
        return 2
    sld_ids = sld_id_lst.findall(q(P_NS, "sldId"))
    if not sld_ids:
        print("ERROR: presentation has no slides")
        return 2

    prm = rel_map(data, "ppt/_rels/presentation.xml.rels")
    last_part = None
    for sid in sld_ids:
        rid = sid.get(q(R_NS, "id"))
        if rid and rid in prm:
            cand = part_from_rel("ppt", prm[rid][1])
            if cand and cand in data:
                last_part = cand
    if not last_part:
        print("ERROR: cannot resolve the final slide part")
        return 2

    if PHRASE.encode("utf-8") in data[last_part]:
        print("OK: %s already ends with the requested final slide (%s); no change made"
              % (src, last_part))
        return 0

    # Reuse the layout of the current final slide so the deck stays visually consistent.
    layout_target = None
    rels_part = posixpath.join(posixpath.dirname(last_part), "_rels",
                               posixpath.basename(last_part) + ".rels")
    for typ, tgt in rel_map(data, rels_part).values():
        if typ == LAYOUT_REL_TYPE:
            layout_target = tgt
            break
    if not layout_target:
        for n in sorted(data):
            if not re.fullmatch(r"ppt/slides/slide\d+\.xml", n):
                continue
            rp = posixpath.join(posixpath.dirname(n), "_rels", posixpath.basename(n) + ".rels")
            for typ, tgt in rel_map(data, rp).values():
                if typ == LAYOUT_REL_TYPE:
                    layout_target = tgt
                    break
            if layout_target:
                break
    if not layout_target:
        print("WARN: no slide layout reference found; adding slide without layout")

    layout_part = part_from_rel("ppt/slides", layout_target) if layout_target else None

    bg = part_bg(data, layout_part) if layout_part else None
    if not bg and layout_part:
        lrp = posixpath.join(posixpath.dirname(layout_part), "_rels",
                             posixpath.basename(layout_part) + ".rels")
        for typ, tgt in rel_map(data, lrp).values():
            if typ == MASTER_REL_TYPE:
                mp = part_from_rel(posixpath.dirname(layout_part), tgt)
                bg = part_bg(data, mp)
                if bg:
                    break

    ti = theme_info(data)
    if bg and len(bg) == 6:
        lum = (0.299 * int(bg[0:2], 16) + 0.587 * int(bg[2:4], 16)
               + 0.114 * int(bg[4:6], 16)) / 255.0
        text_color = (ti["lt1"] or "FFFFFF") if lum < 0.5 else (ti["dk1"] or "1F1F1F")
    else:
        text_color = ti["dk1"] or "1F1F1F"
    font = ti["major"] or "Calibri"

    sld_sz = pres.find(q(P_NS, "sldSz"))
    try:
        cx = int(sld_sz.get("cx"))
        cy = int(sld_sz.get("cy"))
    except Exception:
        cx, cy = 12192000, 6858000

    slide_nums = []
    for n in data:
        m = re.search(r"ppt/slides/slide(\d+)\.xml$", n)
        if m:
            slide_nums.append(int(m.group(1)))
    new_num = max(slide_nums) + 1
    new_part = "ppt/slides/slide%d.xml" % new_num
    new_rels_part = "ppt/slides/_rels/slide%d.xml.rels" % new_num
    if new_part in data:
        print("ERROR: %s unexpectedly exists already" % new_part)
        return 2

    existing_ids = [int(s.get("id")) for s in sld_ids if (s.get("id") or "").isdigit()]
    new_sid = (max(existing_ids) + 1) if existing_ids else 256
    rid_nums = []
    for rid in prm:
        m = re.match(r"rId(\d+)$", rid or "")
        if m:
            rid_nums.append(int(m.group(1)))
    new_rid = "rId%d" % ((max(rid_nums) + 1) if rid_nums else 1)

    slide_xml = build_slide_xml(cx, cy, PHRASE, text_color, font)
    ET.fromstring(slide_xml)  # well-formedness check before writing

    mods = {}
    if layout_target:
        mods[new_rels_part] = build_rels_xml(layout_target).encode("utf-8")
    mods[new_part] = slide_xml.encode("utf-8")

    # 1) presentation.xml: register the new slide in sldIdLst.
    pres_xml = data["ppt/presentation.xml"].decode("utf-8")
    marker = "</p:sldIdLst>" if "</p:sldIdLst>" in pres_xml else None
    if marker is None and "</sldIdLst>" in pres_xml:
        marker = "</sldIdLst>"
    if marker is None:
        print("ERROR: unexpected sldIdLst markup in presentation.xml")
        return 2
    frag = '<p:sldId id="%d" r:id="%s"/>' % (new_sid, new_rid)
    mods["ppt/presentation.xml"] = pres_xml.replace(marker, frag + marker, 1).encode("utf-8")

    # 2) [Content_Types].xml: declare the new slide part.
    ct_xml = data["[Content_Types].xml"].decode("utf-8")
    m = re.search(r'PartName="/ppt/slides/slide\d+\.xml"\s+ContentType="([^"]+)"', ct_xml)
    ct_type = m.group(1) if m else SLIDE_CONTENT_TYPE
    if "</Types>" not in ct_xml:
        print("ERROR: unexpected markup in [Content_Types].xml")
        return 2
    if 'PartName="/%s"' % new_part not in ct_xml:
        frag = '<Override PartName="/%s" ContentType="%s"/>' % (new_part, ct_type)
        ct_xml = ct_xml.replace("</Types>", frag + "</Types>", 1)
    mods["[Content_Types].xml"] = ct_xml.encode("utf-8")

    # 3) presentation.xml.rels: relate the new slide.
    rel_xml = data["ppt/_rels/presentation.xml.rels"].decode("utf-8")
    if "</Relationships>" not in rel_xml:
        print("ERROR: unexpected markup in presentation.xml.rels")
        return 2
    frag = '<Relationship Id="%s" Type="%s" Target="slides/slide%d.xml"/>' \
           % (new_rid, SLIDE_REL_TYPE, new_num)
    mods["ppt/_rels/presentation.xml.rels"] = \
        rel_xml.replace("</Relationships>", frag + "</Relationships>", 1).encode("utf-8")

    # 4) docProps/app.xml: bump slide count if present.
    app_part = "docProps/app.xml"
    if app_part in data:
        app_text = data[app_part].decode("utf-8")

        def _bump(mo):
            return mo.group(1) + str(int(mo.group(2)) + 1) + mo.group(3)

        new_app, n = re.subn(r"(<[^>]*Slides[^>]*>)(\d+)(</[^>]*Slides>)",
                             _bump, app_text, count=1)
        if n:
            mods[app_part] = new_app.encode("utf-8")

    old_count = len(sld_ids)

    # Rebuild the package atomically and replace the source file.
    out_tmp = src + ".new"
    try:
        with zipfile.ZipFile(out_tmp, "w", zipfile.ZIP_DEFLATED) as zo:
            written = set()
            for n in names:
                written.add(n)
                zo.writestr(n, mods.get(n, data[n]))
            for n, blob in mods.items():
                if n not in written:
                    zo.writestr(n, blob)
        os.replace(out_tmp, src)
    finally:
        if os.path.exists(out_tmp):
            try:
                os.remove(out_tmp)
            except OSError:
                pass

    # Post-save verification.
    with zipfile.ZipFile(src) as z2:
        d2 = {n: z2.read(n) for n in z2.namelist()}
    p2 = ET.fromstring(d2["ppt/presentation.xml"])
    lst2 = p2.find(".//" + q(P_NS, "sldIdLst"))
    new_count = len(lst2.findall(q(P_NS, "sldId"))) if lst2 is not None else 0
    if new_count != old_count + 1:
        print("ERROR: slide count is %d, expected %d after save" % (new_count, old_count + 1))
        return 2
    if new_part not in d2 or PHRASE.encode("utf-8") not in d2[new_part]:
        print("ERROR: requested text missing on %s after save" % new_part)
        return 2
    prm2 = rel_map(d2, "ppt/_rels/presentation.xml.rels")
    unresolved = []
    for sid in lst2.findall(q(P_NS, "sldId")):
        rid = sid.get(q(R_NS, "id"))
        tgt = prm2.get(rid, (None, None))[1] if rid else None
        part = part_from_rel("ppt", tgt)
        if not part or part not in d2:
            unresolved.append(rid)
    if unresolved:
        print("ERROR: unresolved slide relationships after save: %s" % unresolved)
        return 2

    print("OK: %s now has %d slides (was %d); final slide %s contains %r"
          % (src, new_count, old_count, new_part, PHRASE))
    return 0


if __name__ == "__main__":
    sys.exit(main())

