    for n in data:
        m = re.search(r"ppt/slides/slide(\d+)\.xml$", n)
        if m:
            slide_nums.append(int(m.group(1)))
    new_num = max(slide_nums) + 1
    new_part = "ppt/slides/slide%d.xml" % new_num
    new_rels_part = "ppt/slides/_rels/slide%d.xml.rels" % new_num
    if new_part in data:
        print("ERROR: %s unexpectedly exists already" % new_part)
        return 2

    existing_ids = [int(s.get("id")) for s in sld_ids if (s.get("id") or "").isdigit()]
    new_sid = (max(existing_ids) + 1) if existing_ids else 256
    rid_nums = []
    for rid in prm:
        m = re.match(r"rId(\d+)$", rid or "")
        if m:
            rid_nums.append(int(m.group(1)))
    new_rid = "rId%d" % ((max(rid_nums) + 1) if rid_nums else 1)

    slide_xml = build_slide_xml(cx, cy, PHRASE, text_color, font)
    ET.fromstring(slide_xml)  # well-formedness check before writing

    mods = {}
    if layout_target:
        mods[new_rels_part] = build_rels_xml(layout_target).encode("utf-8")
    mods[new_part] = slide_xml.encode("utf-8")

    # 1) presentation.xml: register the new slide in sldIdLst.
    pres_xml = data["ppt/presentation.xml"].decode("utf-8")
    marker = "</p:sldIdLst>" if "</p:sldIdLst>" in pres_xml else None
    if marker is None and "</sldIdLst>" in pres_xml:
        marker = "</sldIdLst>"
