        print("ERROR: unexpected sldIdLst markup in presentation.xml")
        return 2
    frag = '<p:sldId id="%d" r:id="%s"/>' % (new_sid, new_rid)
    mods["ppt/presentation.xml"] = pres_xml.replace(marker, frag + marker, 1).encode("utf-8")

    # 2) [Content_Types].xml: declare the new slide part.
    ct_xml = data["[Content_Types].xml"].decode("utf-8")
    m = re.search(r'PartName="/ppt/slides/slide\d+\.xml"\s+ContentType="([^"]+)"', ct_xml)
    ct_type = m.group(1) if m else SLIDE_CONTENT_TYPE
    if "</Types>" not in ct_xml:
        print("ERROR: unexpected markup in [Content_Types].xml")
        return 2
    if 'PartName="/%s"' % new_part not in ct_xml:
        frag = '<Override PartName="/%s" ContentType="%s"/>' % (new_part, ct_type)
        ct_xml = ct_xml.replace("</Types>", frag + "</Types>", 1)
    mods["[Content_Types].xml"] = ct_xml.encode("utf-8")

    # 3) presentation.xml.rels: relate the new slide.
    rel_xml = data["ppt/_rels/presentation.xml.rels"].decode("utf-8")
    if "</Relationships>" not in rel_xml:
        print("ERROR: unexpected markup in presentation.xml.rels")
        return 2
    frag = '<Relationship Id="%s" Type="%s" Target="slides/slide%d.xml"/>' \
           % (new_rid, SLIDE_REL_TYPE, new_num)
    mods["ppt/_rels/presentation.xml.rels"] = \
        rel_xml.replace("</Relationships>", frag + "</Relationships>", 1).encode("utf-8")

    # 4) docProps/app.xml: bump slide count if present.
    app_part = "docProps/app.xml"
    if app_part in data:
        app_text = data[app_part].decode("utf-8")

        def _bump(mo):
            return mo.group(1) + str(int(mo.group(2)) + 1) + mo.group(3)

        new_app, n = re.subn(r"(<[^>]*Slides[^>]*>)(\d+)(</[^>]*Slides>)",
                             _bump, app_text, count=1)
        if n:
            mods[app_part] = new_app.encode("utf-8")

    old_count = len(sld_ids)

    # Rebuild the package atomically and replace the source file.
    out_tmp = src + ".new"
    try:
        with zipfile.ZipFile(out_tmp, "w", zipfile.ZIP_DEFLATED) as zo:
            written = set()
            for n in names:
                written.add(n)
                zo.writestr(n, mods.get(n, data[n]))
            for n, blob in mods.items():
                if n not in written:
                    zo.writestr(n, blob)
        os.replace(out_tmp, src)
    finally:
        if os.path.exists(out_tmp):
            try:
                os.remove(out_tmp)
            except OSError:
                pass

    # Post-save verification.
    with zipfile.ZipFile(src) as z2:
        d2 = {n: z2.read(n) for n in z2.namelist()}
    p2 = ET.fromstring(d2["ppt/presentation.xml"])
    lst2 = p2.find(".//" + q(P_NS, "sldIdLst"))
    new_count = len(lst2.findall(q(P_NS, "sldId"))) if lst2 is not None else 0
    if new_count != old_count + 1:
        print("ERROR: slide count is %d, expected %d after save" % (new_count, old_count + 1))
        return 2
    if new_part not in d2 or PHRASE.encode("utf-8") not in d2[new_part]:
        print("ERROR: requested text missing on %s after save" % new_part)
        return 2
    prm2 = rel_map(d2, "ppt/_rels/presentation.xml.rels")
    unresolved = []
    for sid in lst2.findall(q(P_NS, "sldId")):
        rid = sid.get(q(R_NS, "id"))
        tgt = prm2.get(rid, (None, None))[1] if rid else None
        part = part_from_rel("ppt", tgt)
        if not part or part not in d2:
            unresolved.append(rid)
    if unresolved:
        print("ERROR: unresolved slide relationships after save: %s" % unresolved)
        return 2

    print("OK: %s now has %d slides (was %d); final slide %s contains %r"
          % (src, new_count, old_count, new_part, PHRASE))
    return 0


if __name__ == "__main__":
    sys.exit(main())

